// Validate incoming request
const action = $json.action;
const data = $json.data;
const timestamp = $json.timestamp || new Date().toISOString();
const source = $json.source || 'unknown';

if (!action) {
  return [{
    success: false,
    code: 'MISSING_ACTION',
    error: 'Action field is required',
    timestamp: timestamp
  }];
}

if (!data) {
  return [{
    success: false,
    code: 'MISSING_DATA',
    error: 'Data field is required',
    timestamp: timestamp
  }];
}

console.log(`[${timestamp}] Webhook received: action=${action}, source=${source}`);

return [{
  action: action,
  data: data,
  timestamp: timestamp,
  source: source,
  valid: true
}];

